function ioOptFamily(p){return /maison/i.test(p.type||'')?'maison':/parking|box|terrain|local|immeuble|autre/i.test(p.type||'')?'other':'appartement'}
function ioOptSignature(p){return JSON.stringify([String(p.address||'').trim().toLowerCase(),Number(p.surface)||0,ioOptRooms(p),ioOptFamily(p)])}
