  const key=g?.basis+':'+g?.chargesScope;
  if(!g||!['HC','CC'].includes(g.basis)||!(g.basis==='HC'?g.chargesScope==='excluding-charges':['recoverable','all-inclusive','unknown'].includes(g.chargesScope))||keys.has(key)||!Number.isInteger(g.count)||g.count<0||g.count>100||!Array.isArray(g.references)||g.references.length!==g.count)return false;keys.add(key);
