   if(typeof r.propertyId!=='string'||!r.propertyId||r.propertyId.length>200||urls.has(ioOptUrl(r.url))||propertyIds.has(r.propertyId))return false;urls.add(ioOptUrl(r.url));propertyIds.add(r.propertyId);domains.add(u.hostname.replace(/^www\./,''));return true;
