 if(!a||!uid||a.ownerUid!==uid||a.provider!=='yanport'||a.signature!==ioOptCollectionSignature(p)||!Number.isFinite(Date.parse(a.expiresAt))||Date.parse(a.expiresAt)<=Date.now())return null;
 const snapshot=a.modes?.[mode]?.advertised,q={surface:Number(p.surface),rooms:ioOptRooms(p),family:ioOptFamily(p),communeCode:ioOptConfig(p).communeCode||ioOptConfig(p).analysis?.communeCode};
