  const projection=anil.point*s;if(close&&quality&&charges!==null)return {target:close&&quality&&charges!==null?ioOptRound(Math.max(0,projection-charges)):null,low:close&&quality&&charges!==null?ioOptRound(Math.max(0,anil.low*s-charges)):null,high:close&&quality&&charges!==null?ioOptRound(Math.max(0,anil.high*s-charges)):null,kind:'statistical',label:'Projection du repère ANIL',count:null,refs,sources:['anil'],basis:'HC estimé',geography:(a.city||'Localité')+' · '+(anil.scale==='commune'?'commune':'maille statistique'),projectionCC:Math.round(projection),charges,source:anil,reason:!close?'Surface éloignée du bien type : cible personnelle à renseigner.':!quality?'Qualité statistique insuffisante pour proposer une cible.':charges===null?'Charges à renseigner pour simuler le loyer HC.':''};
