function ioOptFit(){const p=document.getElementById('optimisation'),el=document.getElementById('optimizationMobile');if(!p||!el)return;const active=p.classList.contains('active'),mobile=innerWidth<750,open=!!el.querySelector('details[open]');document.body.classList.toggle('io-opt-fit',active&&mobile&&!open);document.body.classList.remove('io-opt-tight');if(!active||!mobile||open)return;window.scrollTo({top:0,left:0,behavior:'instant'});const nav=document.getElementById('nav'),bottom=Math.min(visualViewport?.height||innerHeight,nav.getBoundingClientRect().top);document.body.classList.toggle('io-opt-tight',bottom-el.getBoundingClientRect().top<550);document.body.style.setProperty('--io-opt-height',Math.max(210,Math.floor(bottom-el.getBoundingClientRect().top-8))+'px');document.body.style.setProperty('--io-opt-nav',nav.getBoundingClientRect().height+'px')}
