 summary.innerHTML='<div class="io-opt-banner">'+ioIcon('arrow')+'<div><span>'+ready.length+' opportunité(s) à étudier</span><strong>'+(complete?ioOptMoney(total,true)+' / mois simulés':'Potentiel à calculer')+'</strong><small>'+(complete?ioOptMoney(total*12,true)+' / an · '+complete+' simulation(s) renseignée(s)':'Renseignez les loyers, modes et hypothèses')+'</small></div></div>';
