 const p=db.properties.find(p=>p.id===pid);if(!p)return;const c=ioOptConfig(p),mode=ioOptMode(p),n=ioOptScenario(p,'nu'),m=ioOptScenario(p,'meuble'),root=document.getElementById('ioOptCompare');root.dataset.propertyId=pid;
