async function ioOptAnalyzeAll(){if(ioOptBusy)return;const properties=db.properties.filter(p=>!ioOptScenario(p,ioOptMode(p)).excluded);if(!properties.length){ioOptState('Aucun logement locatif à analyser.');return}ioOptBusy=true;ioRentCache.clear();ioOptRender();let success=0;try{for(let i=0;i<properties.length;i++){ioOptState('Analyse '+(i+1)+' / '+properties.length+' — '+properties[i].name);try{if(await ioOptAnalyzeOne(properties[i]))success++}catch(e){const p=properties[i],c=ioOptConfig(p);p.optimization={...c,analysis:{...c.analysis,signature:ioOptSignature(p),checkedAt:new Date().toISOString(),sources:c.analysis?.signature===ioOptSignature(p)?(c.analysis.sources||[]).map(s=>({...s,retained:true})):[],errors:[e.message]}}}}ioOptSave();ioOptState(success+' logement(s) avec données disponibles. Consultez Sources et références pour le repère nu et la simulation meublée.')}catch(e){ioOptState('Analyse interrompue : '+e.message)}finally{ioOptBusy=false;ioOptRender()}}
function ioOptInitialize(){document.body.appendChild(document.getElementById('ioOptCompare'));document.getElementById('optimizationAnalyze').onclick=ioOptAnalyzeAll;document.getElementById('optimizationHelp').addEventListener('toggle',ioOptScheduleFit);document.querySelectorAll('[data-opt-filter]').forEach(b=>b.onclick=()=>{ioOptFilter=b.dataset.optFilter;ioOptRender()});window.addEventListener('resize',ioOptScheduleFit);window.visualViewport?.addEventListener('resize',ioOptScheduleFit)}


// Native transport keeps the authentication token outside the WebView. Public
// ANIL/OLL lookups remain available independently of supplier activation.
const ioOptCollectPending=new Map(),ioOptCollectBusy=new Set();
const IO_RENT_ERRORS={AUTH_REQUIRED:'Connectez votre compte ImmOptima pour collecter les annonces.',NOT_CONFIGURED:'Collecte non activée : le service fournisseur doit être configuré.',ACCESS_REQUIRED:'Collecte non activée pour ce compte.',BUSY:'Une collecte est déjà en cours. Réessayez dans un instant.',QUOTA:'Limite de collecte atteinte pour aujourd’hui.',PROVIDER_AUTH:'Accès fournisseur à vérifier par l’administrateur.',PROVIDER_RATE_LIMIT:'Fournisseur temporairement limité. Réessayez plus tard.',PROVIDER_SCHEMA:'Réponse fournisseur non exploitable. Aucune cible remplacée.',PROVIDER_UNAVAILABLE:'Fournisseur indisponible. Vos données sont conservées.',SERVICE_UNAVAILABLE:'Service de collecte indisponible. Vos données sont conservées.',ACCOUNT_CHANGED:'Compte modifié pendant la collecte : résultat ignoré.',INVALID_REQUEST:'Vérifiez la localisation, la surface et le nombre de pièces.',ANDROID_REQUIRED:'Collecte disponible dans l’application Android mise à jour.',TIMEOUT:'La collecte a expiré. Réessayez plus tard.'};
function ioOptCollectTransport(q){return new Promise((resolve,reject)=>{
 if(typeof window==='undefined'||typeof window.AndroidBridge?.immoptimaRentalCollect!=='function'){reject(Error(IO_RENT_ERRORS.ANDROID_REQUIRED));return}
 if(typeof immoptimaAuthState==='undefined'||immoptimaAuthState.status!=='signed_in'){reject(Error(IO_RENT_ERRORS.AUTH_REQUIRED));return}
 const requestId='rental_'+Date.now()+'_'+Math.random().toString(36).slice(2),uid=immoptimaAuthState.uid;
 const timer=setTimeout(()=>{ioOptCollectPending.delete(requestId);reject(Error(IO_RENT_ERRORS.TIMEOUT))},80000);
 ioOptCollectPending.set(requestId,{uid,q,resolve,reject,timer});
 try{window.AndroidBridge.immoptimaRentalCollect(requestId,JSON.stringify(q))}catch{clearTimeout(timer);ioOptCollectPending.delete(requestId);reject(Error(IO_RENT_ERRORS.SERVICE_UNAVAILABLE))}
})}
if(typeof window!=='undefined')window.immoptimaNativeRentalResult=function(payload){
 const pending=ioOptCollectPending.get(payload?.requestId);if(!pending)return;
 clearTimeout(pending.timer);ioOptCollectPending.delete(payload.requestId);
 if(payload.uid!==pending.uid||immoptimaAuthState.status!=='signed_in'||immoptimaAuthState.uid!==pending.uid){pending.reject(Error(IO_RENT_ERRORS.ACCOUNT_CHANGED));return}
 const result=payload.result;
 if(result?.code){pending.reject(Error(IO_RENT_ERRORS[result.code]||IO_RENT_ERRORS.SERVICE_UNAVAILABLE));return}
 if(result?.version!==1||result.provider!=='yanport'||!result.modes||!Number.isFinite(Date.parse(result.checkedAt))||!Number.isFinite(Date.parse(result.expiresAt))||Date.parse(result.expiresAt)<=Date.now()||Date.parse(result.expiresAt)>Date.now()+2*86400000||['nu','meuble'].some(md=>{const m=result.modes[md];return !Array.isArray(m?.references)||m.references.length>100||!Number.isInteger(m.examined)||m.examined<0||m.examined>100||!Array.isArray(m.period)||m.period.some(d=>typeof d!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(d))})){pending.reject(Error(IO_RENT_ERRORS.PROVIDER_SCHEMA));return}
 if(['nu','meuble'].some(md=>result.modes[md].advertised!==undefined&&!ioOptAdvertisedValid(result.modes[md].advertised,md,pending.q))){pending.reject(Error(IO_RENT_ERRORS.PROVIDER_SCHEMA));return}
 pending.resolve({...result,ownerUid:pending.uid});
};
async function ioOptCollect(p,knownGeo){
 if(ioOptCollectBusy.has(p.id))return false;
 ioOptCollectBusy.add(p.id);const before=ioOptSignature(p),beforeSegment=ioOptCollectionSignature(p),uid=typeof immoptimaAuthState!=='undefined'?immoptimaAuthState.uid:'';
 try{
  if(typeof window==='undefined'||typeof window.AndroidBridge?.immoptimaRentalCollect!=='function')throw Error(IO_RENT_ERRORS.ANDROID_REQUIRED);
  if(typeof immoptimaAuthState==='undefined'||immoptimaAuthState.status!=='signed_in')throw Error(IO_RENT_ERRORS.AUTH_REQUIRED);
  const geo=knownGeo||await marketGeocode(p.address||'');if(!geo.city||!geo.postcode||geo.score<.6)throw Error('Adresse insuffisamment précise : vérifiez la commune et le code postal.');
  const result=await ioOptCollectTransport({lat:geo.lat,lon:geo.lon,surface:Number(p.surface),rooms:ioOptRooms(p),family:ioOptFamily(p),communeCode:geo.citycode,city:geo.city,postcode:geo.postcode});
  if(before!==ioOptSignature(p)||beforeSegment!==ioOptCollectionSignature(p)||uid!==immoptimaAuthState.uid||!db.properties.includes(p))throw Error('Bien ou compte modifié : résultat ignoré.');
  // Never accept a result for the wrong property segment, even if the transport succeeds.
  const probe={...p,optimization:{...ioOptConfig(p),communeCode:geo.citycode}};
  for(const md of ['nu','meuble'])if(result.modes[md].references.some(r=>!r||r.mode!==md||typeof r.source!=='string'||r.source.length>300||!Array.isArray(r.urls)||r.urls.length>20||r.urls.some(u=>typeof u!=='string'||u.length>1500||!ioOptUrl(u))||!['HC explicite','CC moins charges explicites'].includes(r.basis)||r.provenance!=='provider'||r.verified!==false||!ioOptReference(probe,{...r,verified:true})||!Number.isFinite(r.distanceM)||r.distanceM<0||r.distanceM>3000||(Date.now()-Date.parse(r.date))/86400000>90))throw Error(IO_RENT_ERRORS.PROVIDER_SCHEMA);
  p.optimization={...ioOptConfig(p),communeCode:geo.citycode};
  p.optimization.collection={...result,signature:ioOptCollectionSignature(p)};delete p.optimization.collectionError;
  return true;
 }catch(e){if(before===ioOptSignature(p)&&uid===(typeof immoptimaAuthState!=='undefined'?immoptimaAuthState.uid:''))p.optimization={...ioOptConfig(p),collectionError:{message:e.message,attemptedAt:new Date().toISOString()}};return false}
 finally{ioOptCollectBusy.delete(p.id)}
}
function ioOptAutoHtml(p){
 const c=ioOptConfig(p),a=c.collection,owned=a&&typeof immoptimaAuthState!=='undefined'&&immoptimaAuthState.status==='signed_in'&&a.ownerUid===immoptimaAuthState.uid;
 const labels={inactive_or_not_rental:'hors location active',type_or_furniture_unknown:'type ou mobilier non confirmé',short_term_or_shared:'courte durée ou partage',lease_duration_unknown:'durée du bail non confirmée',localisation_unknown_or_other_city:'commune ou localisation non confirmée',outside_radius:'au-delà de 3 km',size_or_rooms:'surface ou pièces différentes',date_unknown_or_old:'date absente ou ancienne',charges_or_hc_unknown:'loyer HC indéterminé',inconsistent_charges:'charges incohérentes',source_unknown:'lien source absent',duplicate:'doublon',outlier:'loyer atypique',malformed:'annonce incomplète'};
 return '<article><b>Collecte automatique Nu / Meublé</b><p>Accès fournisseur facultatif, distinct des repères publics gratuits. Comparaison d’annonces en location longue durée, dans la même commune et à moins de 3 km. Surface ±25 %, mêmes pièces, annonces de moins de 90 jours. Au moins 3 logements distincts sont nécessaires.</p><button class="primary" type="button" data-opt-collect '+(ioOptBusy||ioOptCollectBusy.has(p.id)?'disabled':'')+'>Collecter Nu / Meublé</button>'+(c.collectionError?'<p role="status">'+esc(c.collectionError.message)+'</p>':'')+(owned?'<p>Collecte du '+esc(dateFR(a.checkedAt.slice(0,10)))+' · validité 24 h'+(Date.parse(a.expiresAt)<=Date.now()?' · expirée : relancez la collecte':'')+(a.signature!==ioOptCollectionSignature(p)?' · caractéristiques modifiées : relancez':'')+'</p>'+['nu','meuble'].map(md=>{const m=a.modes[md];return '<p><b>'+(md==='nu'?'Nu':'Meublé')+'</b> : '+ioOptAutoReferences(p,md).length+' retenue(s) sur '+Number(m.examined)+' examinée(s)'+(m.period?.length?' · annonces du '+esc(dateFR(m.period[0]))+' au '+esc(dateFR(m.period.at(-1))):'')+(m.truncated?' · recherche plafonnée, échantillon partiel':'')+'.</p><p>'+Object.entries(m.rejected||{}).map(([k,v])=>esc(labels[k]||'autre rejet')+' : '+Number(v)).join(' · ')+'</p>'}).join(''):'<p>Collecte non effectuée pour ce compte. L’accès fournisseur doit être activé côté serveur.</p>')+'<p>Source : Yanport, selon les sites couverts par votre contrat. Les loyers sont des prix annoncés, pas des baux signés. Les liens restent consultables ; leur disponibilité n’est pas garantie. Aucun loyer réel n’est modifié.</p></article>';
}
async function ioOptCollectFromCard(p){if(ioOptBusy||ioOptCollectBusy.has(p.id))return;ioOptModalStatus('Collecte des annonces Nu / Meublé…');const button=document.querySelector('[data-opt-collect]');if(button)button.disabled=true;const ok=await ioOptCollect(p);ioOptSave();const root=document.getElementById('ioOptCompare');if(!root.hidden&&root.dataset.propertyId===p.id){ioOptOpenCompare(p.id,true);ioOptModalStatus(ok?'Collecte terminée. Consultez les références et la période.':ioOptConfig(p).collectionError?.message||'Collecte indisponible.');root.querySelector('[data-opt-collect]')?.scrollIntoView({block:'center'})}}
